//! Exact reimplementation of `std::cout << (float)v` with default stream flags,
//! which libstdc++ implements as `printf("%.6g", (double)v)` in the classic locale.
//!
//! Every step is exact: the binary32 value is expanded as an exact rational
//! `num / den` and rounded to 6 significant decimal digits with round-half-to-even
//! on the *exact* value (glibc rounds the infinitely precise decimal expansion of
//! the argument under the FE_TONEAREST rounding mode).
//!
//! Discriminating inputs that pin the behaviour down (all verified against the
//! C++ oracle built with the same g++ 12.1.0 / glibc):
//!
//! | input (f32 bits) | value            | output          | what it proves                      |
//! |------------------|------------------|-----------------|-------------------------------------|
//! | 0x4996b428       | 1234565          | `1.23456e+06`   | exact tie -> half-to-EVEN (down)     |
//! | 0x4996b478       | 1234575          | `1.23458e+06`   | exact tie -> half-to-EVEN (up)       |
//! | 0x49742450       | 1000005          | `1e+06`         | tie down, then trailing-zero strip   |
//! | 0x497424f0       | 1000015          | `1.00002e+06`   | tie up                               |
//! | 0x497423f8       | 999999.5         | `1e+06`         | exponent taken AFTER rounding        |
//! | 0x38d1b716       | 9.99999975e-05   | `0.0001`        | rounds up to 1e-4 => X=-4 => FIXED   |
//! | 0x3727c5ac       | 1e-05            | `1e-05`         | X=-5 => scientific                   |
//! | 0x47c35000       | 100000           | `100000`        | X=5  => fixed                        |
//! | 0x49742400       | 1000000          | `1e+06`         | X=6  => scientific                   |
//! | 0x00000001       | 1.4013e-45       | `1.4013e-45`    | 3-digit exponent, subnormal          |
//! | 0x7f7fffff       | 3.40282e+38      | `3.40282e+38`   | 2-digit exponent, max normal         |
//! | 0xffc00000       | -NaN             | `-nan`          | sign bit of NaN is printed           |
//! | 0x80000000       | -0.0             | `-0`            | negative zero                        |

use std::cmp::Ordering;

// ---------------------------------------------------------------------------
// Minimal big unsigned integer (little-endian u32 limbs, normalised: no
// trailing zero limbs; the empty vector represents 0).
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
struct Big {
    d: Vec<u32>,
}

impl Big {
    fn from_u64(mut v: u64) -> Big {
        let mut d = Vec::with_capacity(6);
        while v != 0 {
            d.push((v & 0xffff_ffff) as u32);
            v >>= 32;
        }
        Big { d }
    }

    fn is_zero(&self) -> bool {
        self.d.is_empty()
    }

    fn trim(&mut self) {
        while let Some(&0) = self.d.last() {
            self.d.pop();
        }
    }

    fn cmp_big(&self, other: &Big) -> Ordering {
        if self.d.len() != other.d.len() {
            return self.d.len().cmp(&other.d.len());
        }
        for i in (0..self.d.len()).rev() {
            if self.d[i] != other.d[i] {
                return self.d[i].cmp(&other.d[i]);
            }
        }
        Ordering::Equal
    }

    fn mul_u32(&mut self, m: u32) {
        if m == 0 {
            self.d.clear();
            return;
        }
        let mut carry: u64 = 0;
        for limb in self.d.iter_mut() {
            let t = (*limb as u64) * (m as u64) + carry;
            *limb = (t & 0xffff_ffff) as u32;
            carry = t >> 32;
        }
        while carry != 0 {
            self.d.push((carry & 0xffff_ffff) as u32);
            carry >>= 32;
        }
    }

    fn mul_pow10(&mut self, mut e: u32) {
        if self.is_zero() {
            return;
        }
        while e >= 9 {
            self.mul_u32(1_000_000_000);
            e -= 9;
        }
        if e > 0 {
            const P: [u32; 9] = [1, 10, 100, 1000, 10_000, 100_000, 1_000_000, 10_000_000, 100_000_000];
            self.mul_u32(P[e as usize]);
        }
    }

    /// self <<= n  (n in bits)
    fn shl_bits(&mut self, n: usize) {
        if self.is_zero() || n == 0 {
            return;
        }
        let limbs = n / 32;
        let bits = n % 32;
        if bits > 0 {
            let mut carry: u32 = 0;
            for limb in self.d.iter_mut() {
                let nv = (*limb << bits) | carry;
                carry = *limb >> (32 - bits);
                *limb = nv;
            }
            if carry != 0 {
                self.d.push(carry);
            }
        }
        if limbs > 0 {
            let mut nd = vec![0u32; limbs];
            nd.extend_from_slice(&self.d);
            self.d = nd;
        }
    }

    fn shl(&self, n: usize) -> Big {
        let mut c = self.clone();
        c.shl_bits(n);
        c
    }

    /// self -= other  (requires self >= other)
    fn sub_assign(&mut self, other: &Big) {
        let mut borrow: i64 = 0;
        for i in 0..self.d.len() {
            let o = if i < other.d.len() { other.d[i] as i64 } else { 0 };
            let mut t = self.d[i] as i64 - o - borrow;
            if t < 0 {
                t += 1i64 << 32;
                borrow = 1;
            } else {
                borrow = 0;
            }
            self.d[i] = t as u32;
        }
        debug_assert_eq!(borrow, 0);
        self.trim();
    }

    fn pow10(e: u32) -> Big {
        let mut b = Big::from_u64(1);
        b.mul_pow10(e);
        b
    }

    fn pow2(e: usize) -> Big {
        Big::from_u64(1).shl(e)
    }
}

// ---------------------------------------------------------------------------
// The formatter
// ---------------------------------------------------------------------------

const PREC: i32 = 6; // default std::ostream precision

/// Format `v` exactly as `std::cout << v` does with default stream flags
/// (equivalently `printf("%.6g", (double)v)` in the "C" locale).
pub fn fmt_cout(v: f32) -> String {
    let bits = v.to_bits();
    let neg = (bits >> 31) != 0;
    let exp_field = ((bits >> 23) & 0xff) as i32;
    let mant_field = bits & 0x007f_ffff;

    // --- specials -----------------------------------------------------------
    if exp_field == 0xff {
        return if mant_field != 0 {
            if neg { "-nan".to_string() } else { "nan".to_string() }
        } else if neg {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }
    if exp_field == 0 && mant_field == 0 {
        return if neg { "-0".to_string() } else { "0".to_string() };
    }

    // --- exact value as m * 2^e --------------------------------------------
    let (m, e): (u64, i32) = if exp_field == 0 {
        (mant_field as u64, -149)
    } else {
        ((mant_field as u64) | (1u64 << 23), exp_field - 127 - 23)
    };

    // exact rational num/den == |v|
    let (num, den) = if e >= 0 {
        (Big::from_u64(m).shl(e as usize), Big::from_u64(1))
    } else {
        (Big::from_u64(m), Big::pow2((-e) as usize))
    };

    // --- decimal exponent k with 10^(k-1) <= |v| < 10^k ---------------------
    let k = find_k(&num, &den, v.abs() as f64);

    // --- round |v| / 10^(k-PREC) to an integer, half-to-even ----------------
    // result lies in [10^(PREC-1), 10^PREC]
    let s = PREC - k;
    let (mut a, b) = if s >= 0 {
        let mut a = num.clone();
        a.mul_pow10(s as u32);
        (a, den.clone())
    } else {
        let mut b = den.clone();
        b.mul_pow10((-s) as u32);
        (num.clone(), b)
    };

    // quotient is < 2^20 (it is < 10^6), so 20 shift/subtract steps suffice
    let mut q: u64 = 0;
    for sh in (0..20usize).rev() {
        let t = b.shl(sh);
        if t.cmp_big(&a) != Ordering::Greater {
            a.sub_assign(&t);
            q |= 1u64 << sh;
        }
    }
    // a is now the remainder; round half to even on 2*rem vs den
    let twice = a.shl(1);
    match twice.cmp_big(&b) {
        Ordering::Greater => q += 1,
        Ordering::Equal => {
            if q & 1 == 1 {
                q += 1;
            }
        }
        Ordering::Less => {}
    }

    // --- digits + decimal exponent AFTER rounding ---------------------------
    let (digits, x): (String, i32) = if q == 1_000_000 {
        ("100000".to_string(), k) // carried out of the 6-digit window
    } else {
        (format!("{:06}", q), k - 1)
    };

    // --- %g style selection -------------------------------------------------
    let mut out = String::with_capacity(16);
    if neg {
        out.push('-');
    }
    if x < -4 || x >= PREC {
        // scientific: d.ddddd e(+|-)dd
        out.push(digits.as_bytes()[0] as char);
        let frac = strip_zeros(&digits[1..]);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        out.push('e');
        out.push(if x < 0 { '-' } else { '+' });
        let ax = x.unsigned_abs();
        if ax < 10 {
            out.push('0');
        }
        out.push_str(&ax.to_string());
    } else if x >= 0 {
        let split = (x as usize) + 1;
        out.push_str(&digits[..split]);
        let frac = strip_zeros(&digits[split..]);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
    } else {
        // -4 <= x <= -1 : 0.000ddd...
        let lead = (-x - 1) as usize;
        let mut frac = String::with_capacity(lead + 6);
        for _ in 0..lead {
            frac.push('0');
        }
        frac.push_str(&digits);
        let frac = strip_zeros(&frac);
        out.push('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
    }
    out
}

fn strip_zeros(s: &str) -> &str {
    s.trim_end_matches('0')
}

/// Smallest k with |v| < 10^k, i.e. 10^(k-1) <= |v| < 10^k.
/// `approx` is |v| as f64 (exact) and is used only as a starting guess; the
/// loop then verifies/corrects with exact big-integer comparisons.
fn find_k(num: &Big, den: &Big, approx: f64) -> i32 {
    let mut k = if approx > 0.0 {
        (approx.log10().floor() as i32) + 1
    } else {
        1
    };
    loop {
        if cmp_pow10(num, den, k) != Ordering::Less {
            k += 1;
            continue;
        }
        if cmp_pow10(num, den, k - 1) == Ordering::Less {
            k -= 1;
            continue;
        }
        return k;
    }
}

/// Compare num/den against 10^k exactly.
fn cmp_pow10(num: &Big, den: &Big, k: i32) -> Ordering {
    if k >= 0 {
        let mut rhs = den.clone();
        rhs.mul_pow10(k as u32);
        num.cmp_big(&rhs)
    } else {
        let mut lhs = num.clone();
        lhs.mul_pow10((-k) as u32);
        lhs.cmp_big(den)
    }
}

/// Convenience: assemble a whole output line the way the target program does
/// (values separated by single spaces).
pub fn fmt_line(vals: &[f32]) -> String {
    let mut s = String::new();
    for (i, v) in vals.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(&fmt_cout(*v));
    }
    s
}
