mod fmt_cout;
use fmt_cout::fmt_cout;
use std::io::{Read, Write, BufWriter};

fn hexline(b: u32, out: &mut Vec<u8>) {
    const H: &[u8; 16] = b"0123456789abcdef";
    for i in (0..8).rev() {
        out.push(H[((b >> (i * 4)) & 0xf) as usize]);
    }
    out.push(b'\n');
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // splitmix64
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
}

fn gen(spec: &str, out: &mut dyn Write) {
    let mut buf: Vec<u8> = Vec::with_capacity(1 << 22);
    let mut emit = |b: u32, buf: &mut Vec<u8>, out: &mut dyn Write| {
        hexline(b, buf);
        if buf.len() >= (1 << 22) {
            out.write_all(buf).unwrap();
            buf.clear();
        }
    };
    match spec {
        // exhaustive sweeps: all 2^23 mantissas for a critical exponent field,
        // both signs -> 2^24 patterns per exponent field
        "exh" => {
            // critical exponent fields: subnormals(0), around 1.0 (126,127),
            // around 1e-5/1e-4 boundary (113 -> ~1e-4), around 1e6 (146),
            // near max (254), near the fixed/scientific switch (149 ~ 1e5..)
            for &ef in &[0u32, 126, 127, 113, 146, 149, 254, 100] {
                for m in 0..(1u32 << 23) {
                    emit((ef << 23) | m, &mut buf, out);
                    emit((1 << 31) | (ef << 23) | m, &mut buf, out);
                }
            }
        }
        "rand" => {
            let mut r = Rng(0xDEADBEEF12345678);
            for _ in 0..30_000_000u64 {
                emit(r.next() as u32, &mut buf, out);
            }
        }
        // every pattern within +-64 ulp of every decimal power of ten 1e-45..1e38
        "pow10" => {
            for p in -45i32..=38 {
                let s = format!("1e{}", p);
                let v: f32 = s.parse().unwrap();
                if !v.is_finite() {
                    continue;
                }
                let b = v.to_bits();
                for d in -64i64..=64 {
                    let nb = (b as i64) + d;
                    if nb < 0 || nb > 0xffff_ffff {
                        continue;
                    }
                    emit(nb as u32, &mut buf, out);
                    emit((nb as u32) | (1 << 31), &mut buf, out);
                }
            }
        }
        // all subnormals with mantissa < 2^16, both signs
        "sub" => {
            for m in 0..(1u32 << 16) {
                emit(m, &mut buf, out);
                emit((1 << 31) | m, &mut buf, out);
            }
        }
        // near every "round to 6 digits" boundary: integers 10^5..10^7 that are
        // exactly representable, plus specials
        "spec" => {
            let mut v: Vec<u32> = Vec::new();
            for b in [
                0x7f800000u32, 0xff800000, 0x7fc00000, 0xffc00000, 0x7f800001, 0xff800001,
                0x7fffffff, 0xffffffff, 0x00000000, 0x80000000, 0x00000001, 0x80000001,
                0x007fffff, 0x00800000, 0x7f7fffff, 0xff7fffff,
            ] {
                v.push(b);
            }
            for i in 100_000i64..=16_777_216 {
                let f = i as f32;
                if f as i64 == i {
                    v.push(f.to_bits());
                    v.push(f.to_bits() | (1 << 31));
                }
            }
            for x in v {
                emit(x, &mut buf, out);
            }
        }
        _ => panic!("bad spec"),
    }
    out.write_all(&buf).unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = args.get(1).map(|s| s.as_str()).unwrap_or("fmt");
    let stdout = std::io::stdout();
    if mode == "gen" {
