            if t < 0 {
                t += 1i64 << 32;
                borrow = 1;
            } else {
                borrow = 0;
            }
            self.d[i] = t as u32;
        }
        debug_assert_eq!(borrow, 0);
        self.trim();
    }

    fn pow2(e: usize) -> Big {
        Big::from_u64(1).shl(e)
    }
