    // `a` is now the exact remainder; round half-to-even on 2*rem vs divisor.
    // Ties really do occur (the decimal expansion of a binary float is finite):
    // 1234565 -> stays 123456 (even), 1234575 -> 123458 (7 was odd).
    let twice = a.shl(1);
    match twice.cmp_big(&b) {
        Ordering::Greater => q += 1,
        Ordering::Equal => {
            if q & 1 == 1 {
                q += 1;
            }
        }
        Ordering::Less => {}
    }

    // --- digits + decimal exponent AFTER rounding ---------------------------
    // 999999.5f rounds to 10^6, which bumps the exponent from 5 to 6 and
    // therefore flips the %g style from fixed to scientific.
    let (digits, x): (String, i32) = if q == 1_000_000 {
        ("100000".to_string(), k) // carry out of the 6-digit window
    } else {
        (format!("{:06}", q), k - 1)
    };

    // --- %g style selection -------------------------------------------------
    let mut out = String::with_capacity(16);
    if neg {
        out.push('-');
    }
    if x < -4 || x >= PREC {
        // scientific: d[.ddddd]e(+|-)dd  (>=2 exponent digits, 3 when needed)
        out.push(digits.as_bytes()[0] as char);
        let frac = strip_zeros(&digits[1..]);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        out.push('e');
        out.push(if x < 0 { '-' } else { '+' });
        let ax = x.unsigned_abs();
        if ax < 10 {
            out.push('0');
        }
        out.push_str(&ax.to_string());
    } else if x >= 0 {
        // fixed, decimal point after x+1 digits
        let split = (x as usize) + 1;
        out.push_str(&digits[..split]);
        let frac = strip_zeros(&digits[split..]);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
    } else {
        // fixed, -4 <= x <= -1 : 0.000ddd...
        let lead = (-x - 1) as usize;
        let mut frac = String::with_capacity(lead + 6);
        for _ in 0..lead {
            frac.push('0');
        }
        frac.push_str(&digits);
        let frac = strip_zeros(&frac);
        out.push('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
    }
    out
}

fn strip_zeros(s: &str) -> &str {
    s.trim_end_matches('0')
}

/// Smallest `k` with `|v| < 10^k`, i.e. `10^(k-1) <= |v| < 10^k`.
/// `approx` is `|v|` widened to f64 (exact) and is used only as a starting
/// guess; the loop then verifies/corrects with exact big-integer comparisons,
/// so a mis-seed costs iterations, never correctness.
fn find_k(num: &Big, den: &Big, approx: f64) -> i32 {
    let mut k = if approx > 0.0 {
        (approx.log10().floor() as i32) + 1
    } else {
        1
    };
    loop {
        if cmp_pow10(num, den, k) != Ordering::Less {
            k += 1;
            continue;
        }
        if cmp_pow10(num, den, k - 1) == Ordering::Less {
            k -= 1;
            continue;
        }
        return k;
    }
}

/// Compare `num/den` against `10^k` exactly.
fn cmp_pow10(num: &Big, den: &Big, k: i32) -> Ordering {
    if k >= 0 {
        let mut rhs = den.clone();
        rhs.mul_pow10(k as u32);
        num.cmp_big(&rhs)
    } else {
        let mut lhs = num.clone();
        lhs.mul_pow10((-k) as u32);
        lhs.cmp_big(den)
    }
}

/// Assemble a whole output line the way the target program does: values
/// separated by single spaces. The driver terminates the line with
/// `std::endl`, i.e. a single '\n' (plus a flush).
pub fn fmt_line(vals: &[f32]) -> String {
    let mut s = String::new();
    for (i, v) in vals.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(&fmt_cout(*v));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn f(bits: u32) -> String {
        fmt_cout(f32::from_bits(bits))
    }

    #[test]
    fn specials() {
        assert_eq!(f(0x7fc00000), "nan");
        assert_eq!(f(0xffc00000), "-nan");
        assert_eq!(f(0x7f800000), "inf");
        assert_eq!(f(0xff800000), "-inf");
        assert_eq!(f(0x00000000), "0");
        assert_eq!(f(0x80000000), "-0");
    }

    #[test]
    fn exact_ties_are_half_to_even() {
        assert_eq!(f(0x4996b428), "1.23456e+06"); // 1234565, kept digit even
        assert_eq!(f(0x4996b478), "1.23458e+06"); // 1234575, kept digit odd
        assert_eq!(f(0x49742450), "1e+06"); // 1000005
        assert_eq!(f(0x497424f0), "1.00002e+06"); // 1000015
    }

    #[test]
    fn exponent_is_computed_after_rounding() {
        assert_eq!(f(0x497423f8), "1e+06"); // 999999.5
        assert_eq!(f(0x38d1b716), "0.0001"); // 9.99999975e-05
    }

    #[test]
    fn style_thresholds() {
        assert_eq!(f(0x3727c5ac), "1e-05");
        assert_eq!(f(0x38d1b717), "0.0001");
        assert_eq!(f(0x47c35000), "100000");
        assert_eq!(f(0x49742400), "1e+06");
    }

    #[test]
    fn extremes() {
        assert_eq!(f(0x00000001), "1.4013e-45");
        assert_eq!(f(0x7f7fffff), "3.40282e+38");
        assert_eq!(f(0x3f800000), "1");
        assert_eq!(f(0x323bcc77), "1.09278e-08");
    }

    #[test]
    fn line() {
        assert_eq!(fmt_line(&[0.0, -0.0, 1.0]), "0 -0 1");
    }
}
